    tp=P[town]; tp2=P[town2]
    best={0:0}
    def rec(i,a,b,c,d):
        pass
    # enumerate
    for a in range(CAP+1):
        for b in range(CAP+1-a):
            for c in range(CAP+1-a-b):
                for d in range(CAP+1-a-b-c):
                    cart=(a,b,c,d)
                    cost=sum(cart[i]*tp[g] for i,g in enumerate(GOODS))
                    rev=sum(cart[i]*tp2[g] for i,g in enumerate(GOODS))
                    if rev>best.get(cost,0): best[cost]=rev
    # pareto: keep points where no other has cost<= and rev>=
    pts=sorted(best.items())  # by cost
    fr=[]
    maxrev=-1
    for cost,rev in pts:
        if rev>maxrev:
            fr.append((cost,rev)); maxrev=rev
    return fr

FR={(t,t2):frontier(t,t2) for t in TOWNS for t2 in TOWNS if t!=t2}
for k in FR:
